<section class="auth-card auth-card-wide"><p class="eyebrow"><?= e(country()->name()) ?> · <?= e(country()->currencyCode()) ?></p><h1><?= e(__('auth.register')) ?></h1><p class="muted">Your investment region is set securely from your current Country Pack. You can choose your interface language later without changing it.</p><form method="post" action="<?= e(route('register.store')) ?>" class="form-stack"><?= app('csrf')->input() ?><div class="form-grid"><label class="field">First name<input name="first_name" autocomplete="given-name" required value="<?= e($_SESSION['_old']['first_name']??'') ?>"></label><label class="field">Last name<input name="last_name" autocomplete="family-name" required value="<?= e($_SESSION['_old']['last_name']??'') ?>"></label></div><label class="field">Email address<input type="email" name="email" autocomplete="email" required value="<?= e($_SESSION['_old']['email']??'') ?>"></label><label class="field">Phone <span class="muted">(optional)</span><input type="tel" name="phone" autocomplete="tel" value="<?= e($_SESSION['_old']['phone']??'') ?>"></label><label class="field">Password<input type="password" name="password" autocomplete="new-password" aria-describedby="password-help" required></label><p id="password-help" class="help">Use 12 or more characters with uppercase, lowercase and a number.</p><label class="field">Confirm password<input type="password" name="password_confirmation" autocomplete="new-password" required></label><label class="check"><input type="checkbox" name="terms" value="1" required> I accept the <a href="#">Terms</a>.</label><label class="check"><input type="checkbox" name="privacy" value="1" required> I accept the <a href="#">Privacy Policy</a>.</label><button class="button" type="submit">Create secure account</button></form><p class="auth-links">Already have an account? <a href="<?= e(route('login')) ?>">Sign in</a></p></section>
